let mounted=false,consent=false,configuration=null,session='',viewSent=false;
const protectedChoice=()=>navigator.globalPrivacyControl===true||navigator.doNotTrack==='1';
const cleanUTM=value=>/^[a-zA-Z0-9_. -]{0,80}$/.test(value||'')?value||'':'';
export function recordEvent(name,properties={}){if(!consent||!configuration?.tracking||protectedChoice()||location.pathname.startsWith('/dashboard'))return;const parameters=new URLSearchParams(location.search);let attribution={source:cleanUTM(parameters.get('utm_source')),medium:cleanUTM(parameters.get('utm_medium')),campaign:cleanUTM(parameters.get('utm_campaign')),referrer:document.referrer};try{const saved=JSON.parse(sessionStorage.getItem('sub-attribution')||'null');if(saved)attribution=saved;else{if(attribution.referrer&&new URL(attribution.referrer).origin===location.origin)attribution.referrer='';sessionStorage.setItem('sub-attribution',JSON.stringify(attribution))}}catch{}const payload={id:crypto.randomUUID(),session,name,consent:true,path:location.pathname,...attribution,device:matchMedia('(max-width:760px)').matches?'mobile':'desktop',properties};fetch('/api/events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),keepalive:true}).catch(()=>{});}
function pageView(){if(!viewSent&&consent){viewSent=true;recordEvent('page_view')}}
export async function initializeAnalytics(){if(mounted)return;mounted=true;if(location.pathname.startsWith('/dashboard'))return;try{const r=await fetch('/api/config');if(!r.ok)return;configuration=await r.json();if(!configuration.tracking)return}catch{return}
 try{session=sessionStorage.getItem('sub-session')||crypto.randomUUID();sessionStorage.setItem('sub-session',session);consent=localStorage.getItem('sub-analytics')==='granted'}catch{session=crypto.randomUUID()}
 if(protectedChoice())consent=false;
 const panel=document.createElement('aside');panel.className='privacy-dock';panel.setAttribute('aria-label','Anonymous analytics preference');panel.hidden=true;
 panel.innerHTML='<h2>Anonymous audience analytics</h2><p>Count page visits and interactions to understand which work resonates. No fingerprinting or raw IP addresses are stored in audience events.</p><div class="privacy-buttons"><button type="button" data-analytics-allow>Allow analytics</button><button type="button" data-analytics-deny>Not now</button></div><small>You can change this from Privacy / analytics in the footer.</small>';
 document.body.append(panel);
 function show(){panel.hidden=false;if(protectedChoice()){panel.querySelector('p').textContent='Your browser’s privacy preference is active. Optional audience analytics are off.';panel.querySelector('[data-analytics-allow]').hidden=true}}
 function choose(value){consent=value&&!protectedChoice();try{localStorage.setItem('sub-analytics',consent?'granted':'denied')}catch{}panel.hidden=true;pageView()}
 panel.querySelector('[data-analytics-allow]').addEventListener('click',()=>choose(true));panel.querySelector('[data-analytics-deny]').addEventListener('click',()=>choose(false));
 document.addEventListener('click',event=>{if(event.target.closest('[data-privacy-open]'))show();if(event.target.closest('[data-resume-download]'))recordEvent('resume_download');const item=event.target.closest('[data-open]');if(item)recordEvent('case_open',{case:item.dataset.open});const external=event.target.closest('a[href^="http"]');if(external&&new URL(external.href).origin!==location.origin)recordEvent('outbound_click',{destination:new URL(external.href).hostname});const choice=event.target.closest('a[href^="concept-"]');if(choice)recordEvent('concept_select',{variant:choice.getAttribute('href').replace('concept-','').replace('.html','')})});
 let engaged=0,sent=false,last=performance.now();const timer=setInterval(()=>{const now=performance.now();if(!document.hidden)engaged+=Math.min(2,(now-last)/1000);last=now;if(engaged>=15&&!sent&&consent){sent=true;recordEvent('engagement');clearInterval(timer)}},1000);window.addEventListener('pagehide',()=>clearInterval(timer),{once:true});
 window.addEventListener('portfolio:themechange',event=>recordEvent('theme_change',{theme:event.detail.theme}));
 document.addEventListener('play',event=>{if(event.target instanceof HTMLVideoElement)recordEvent('film_play',{film:event.target.dataset.reelVideo||'study'})},true);
 window.addEventListener('storage',event=>{if(event.key==='sub-analytics'){consent=event.newValue==='granted'&&!protectedChoice();pageView()}});
 let choice=null;try{choice=localStorage.getItem('sub-analytics')}catch{}if(choice===null&&!protectedChoice())show();pageView();
}
